ffmpeg -y -i clips/shot25.mp4 -t 1.2 -vf "scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,fps=30,setsar=1,format=yuv420p" -an -c:v libx264 -crf 16 -preset slow norm/s25.mp4   # 화면 1.2s + 전환여유 0.0s
