ffmpeg -y -f lavfi -i color=c=black:s=1080x1920:r=30 -t 0.24 -vf "scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,fps=30,setsar=1,format=yuv420p" -an -c:v libx264 -crf 16 -preset slow norm/s27.mp4   # 화면 0.24s + 전환여유 0.0s

# ② 컷/디졸브 조립 + 색보정 + 자막  (완성 길이 ≈ 52.41s)
ffmpeg -y -i norm/s01.mp4 -i norm/s02.mp4 -i norm/s03.mp4 -i norm/s04.mp4 -i norm/s05.mp4 -i norm/s06.mp4 -i norm/s07.mp4 -i norm/s08.mp4 -i norm/s09.mp4 -i norm/s10.mp4 -i norm/s11.mp4 -i norm/s12.mp4 -i norm/s13.mp4 -i norm/s14.mp4 -i norm/s15.mp4 -i norm/s16.mp4 -i norm/s17.mp4 -i norm/s18.mp4 -i norm/s19.mp4 -i norm/s20.mp4 -i norm/s21.mp4 -i norm/s22.mp4 -i norm/s23.mp4 -i norm/s24.mp4 -i norm/s25.mp4 -i norm/s26.mp4 -i norm/s27.mp4 -filter_complex "[0:v]setpts=PTS-STARTPTS[v1];[1:v]setpts=PTS-STARTPTS[v2];[2:v]setpts=PTS-STARTPTS[v3];[3:v]setpts=PTS-STARTPTS[v4];[4:v]setpts=PTS-STARTPTS[v5];[5:v]setpts=PTS-STARTPTS[v6];[6:v]setpts=PTS-STARTPTS[v7];[7:v]setpts=PTS-STARTPTS[v8];[8:v]setpts=PTS-STARTPTS[v9];[9:v]setpts=PTS-STARTPTS[v10];[10:v]setpts=PTS-STARTPTS[v11];[11:v]setpts=PTS-STARTPTS[v12];[12:v]setpts=PTS-STARTPTS[v13];[13:v]setpts=PTS-STARTPTS[v14];[14:v]setpts=PTS-STARTPTS[v15];[15:v]setpts=PTS-STARTPTS[v16];[16:v]setpts=PTS-STARTPTS[v17];[17:v]setpts=PTS-STARTPTS[v18];[18:v]setpts=PTS-STARTPTS[v19];[19:v]setpts=PTS-STARTPTS[v20];[20:v]setpts=PTS-STARTPTS[v21];[21:v]setpts=PTS-STARTPTS[v22];[22:v]setpts=PTS-STARTPTS[v23];[23:v]setpts=PTS-STARTPTS[v24];[24:v]setpts=PTS-STARTPTS[v25];[25:v]setpts=PTS-STARTPTS[v26];[26:v]setpts=PTS-STARTPTS[v27];[v1][v2]concat=n=2:v=1:a=0[j1];[j1][v3]concat=n=2:v=1:a=0[j2];[j2][v4]concat=n=2:v=1:a=0[j3];[j3][v5]concat=n=2:v=1:a=0[j4];[j4][v6]concat=n=2:v=1:a=0[j5];[j5][v7]concat=n=2:v=1:a=0[j6];[j6][v8]concat=n=2:v=1:a=0[j7];[j7][v9]concat=n=2:v=1:a=0[j8];[j8][v10]concat=n=2:v=1:a=0[j9];[j9][v11]concat=n=2:v=1:a=0[j10];[j10][v12]concat=n=2:v=1:a=0[j11];[j11][v13]concat=n=2:v=1:a=0[j12];[j12][v14]concat=n=2:v=1:a=0[j13];[j13][v15]concat=n=2:v=1:a=0[j14];[j14][v16]concat=n=2:v=1:a=0[j15];[j15][v17]concat=n=2:v=1:a=0[j16];[j16][v18]concat=n=2:v=1:a=0[j17];[j17][v19]concat=n=2:v=1:a=0[j18];[j18][v20]concat=n=2:v=1:a=0[j19];[j19][v21]concat=n=2:v=1:a=0[j20];[j20][v22]concat=n=2:v=1:a=0[j21];[j21][v23]concat=n=2:v=1:a=0[j22];[j22][v24]concat=n=2:v=1:a=0[j23];[j23][v25]concat=n=2:v=1:a=0[j24];[j24][v26]concat=n=2:v=1:a=0[j25];[j25][v27]concat=n=2:v=1:a=0[j26];[j26]eq=contrast=1.06:saturation=0.95:gamma=0.98,colorbalance=rs=0.04:gs=0.01:bs=-0.03:rh=0.03:bh=-0.02,noise=alls=7:allf=t,vignette=PI/5,subtitles=subs.srt:fontsdir=fonts:force_style='FontName=Pretendard,FontSize=13,PrimaryColour=&H00FFFFFF,OutlineColour=&H00000000,BorderStyle=1,Outline=2,Shadow=0,Alignment=2,MarginV=80'[vout]" -map "[vout]" -c:v libx264 -crf 17 -preset slow -pix_fmt yuv420p video_only.mp4

# ③ 사운드: BGM(-dB 베이스) + 효과음을 타임코드에 정확히 배치 → -14 LUFS (쇼츠/릴스 표준)
ffmpeg -y -i audio/bgm.mp3 -i sfx/sfx01.wav -i sfx/sfx02.wav -i sfx/sfx03.wav -i sfx/sfx04.wav -i sfx/sfx05.wav -i sfx/sfx06.wav -i sfx/sfx07.wav -filter_complex "[0:a]atrim=0:52.41,volume=-18dB,afade=t=out:st=51.61:d=0.8[bgm];[1:a]adelay=0|0,volume=0dB[s1];[2:a]adelay=3400|3400,volume=0dB[s2];[3:a]adelay=6000|6000,volume=0dB[s3];[4:a]adelay=36300|36300,volume=0dB[s4];[5:a]adelay=38700|38700,volume=0dB[s5];[6:a]adelay=44000|44000,volume=0dB[s6];[7:a]adelay=52170|52170,volume=0dB[s7];[bgm][s1][s2][s3][s4][s5][s6][s7]amix=inputs=8:normalize=0,loudnorm=I=-14:TP=-1.5:LRA=11[aout]" -map "[aout]" -ar 48000 mix.wav

# ④ 합치기 (인스타/쇼츠 업로드용: H.264 High, AAC 320k, faststart)
ffmpeg -y -i video_only.mp4 -i mix.wav -map 0:v -map 1:a -c:v copy -c:a aac -b:a 320k -shortest -movflags +faststart final.mp4
